/**
 * The text emitters. Every generated file in src/ is produced here.
 *
 * Output is hand-tuned to be byte-identical to what Biome would format, rather
 * than being piped through a formatter. That keeps the generator dependency-free
 * and, more usefully, keeps `--check` meaningful: if the emitter and Biome ever
 * disagree, `bun run lint` fails loudly instead of the two quietly fighting over
 * the same tracked file on every commit.
 *
 * The one non-obvious piece is `renderElement`, which reproduces Biome's
 * attribute line-breaking: an element that fits inside the 100-column limit stays
 * on one line, and one that does not gets one attribute per line. The `settings`
 * icon's path data is long enough to need this, so it is exercised by the real
 * icon set rather than only by tests.
 */

import { byString } from "./io.mjs";
import { toJsxChildren } from "./svg.mjs";

const BANNER_SCRIPT = "scripts/generate.mjs";
const LINE_WIDTH = 100;

/** Emit the React component for one icon. */
export function emitComponent({ icon, component }) {
  const children = toJsxChildren(icon.tree)
    .map((element) => renderElement(element, 6))
    .join("\n");

  return `/* GENERATED by ${BANNER_SCRIPT} from ${icon.file}. Do not edit by hand. */
import { IconBase } from "../icon-base.js";
import type { QeetrixIconProps } from "../types.js";

export function ${component}(props: QeetrixIconProps) {
  return (
    <IconBase {...props}>
${children}
    </IconBase>
  );
}
`;
}

/**
 * Render one JSX element, matching Biome's formatting.
 *
 * Biome's actual rule, established by probing it rather than assumed: an element
 * with a *single* attribute is never broken across lines, however long it is —
 * the value is an unbreakable string literal, so breaking buys nothing. An
 * element with two or more attributes is broken one-per-line once the
 * single-line form exceeds the line width.
 *
 * This matters for real icons: `settings` has one very long `d` and must stay on
 * one line, while a `rect` with seven attributes must break.
 */
function renderElement(element, indentWidth) {
  const indent = " ".repeat(indentWidth);
  const attrs = element.props.map(([name, value]) => `${name}=${JSON.stringify(value)}`);
  const inner = element.children.map((child) => renderElement(child, indentWidth + 2)).join("\n");

  const openSingle = `<${element.name}${attrs.length ? ` ${attrs.join(" ")}` : ""}`;
  const fitsOneLine =
    attrs.length <= 1 ||
    indentWidth + openSingle.length + (element.children.length ? 1 : 3) <= LINE_WIDTH;

  if (fitsOneLine) {
    if (element.children.length === 0) return `${indent}${openSingle} />`;
    return `${indent}${openSingle}>\n${inner}\n${indent}</${element.name}>`;
  }

  const brokenAttrs = attrs.map((attr) => `${indent}  ${attr}`).join("\n");
  if (element.children.length === 0) {
    return `${indent}<${element.name}\n${brokenAttrs}\n${indent}/>`;
  }
  return `${indent}<${element.name}\n${brokenAttrs}\n${indent}>\n${inner}\n${indent}</${element.name}>`;
}

/** Emit the generated barrel that re-exports every icon component. */
export function emitBarrel(entries) {
  const lines = [...entries]
    .sort((a, b) => byString(a.component, b.component))
    .map((entry) => `export { ${entry.component} } from "./${entry.name}.js";`)
    .join("\n");

  return `/* GENERATED by ${BANNER_SCRIPT}. Do not edit by hand. */
${lines}
`;
}

/** Emit the searchable metadata catalogue. */
export function emitMetadata(entries) {
  const sorted = [...entries].sort((a, b) => byString(a.name, b.name));

  const records = sorted
    .map((entry) =>
      [
        "  {",
        `    name: ${JSON.stringify(entry.name)},`,
        `    component: ${JSON.stringify(entry.component)},`,
        `    category: ${JSON.stringify(entry.category)},`,
        `    tags: ${renderStringArray(entry.tags, 4)},`,
        `    aliases: ${renderStringArray(entry.aliases, 4)},`,
        `    mirror: ${entry.mirror},`,
        // Omitted entirely when absent, so `deprecated` in a consumer's code is
        // a truthy check rather than a comparison against a sentinel.
        ...(entry.deprecated
          ? [
              "    deprecated: {",
              `      since: ${JSON.stringify(entry.deprecated.since)},`,
              `      replacement: ${JSON.stringify(entry.deprecated.replacement ?? null)},`,
              `      reason: ${JSON.stringify(entry.deprecated.reason)},`,
              "    },",
            ]
          : []),
        "  },",
      ].join("\n"),
    )
    .join("\n");

  const names = sorted.map((entry) => `  ${JSON.stringify(entry.name)},`).join("\n");

  return `/* GENERATED by ${BANNER_SCRIPT}. Do not edit by hand. */
import type { IconMetadata } from "./types.js";

/**
 * Every icon in the library, sorted by name.
 *
 * Importable on its own via \`@qeetrix/icons/metadata\`, so an icon picker or a
 * docs search can read the whole catalogue without pulling a single component
 * into the bundle.
 */
export const icons: readonly IconMetadata[] = [
${records}
];

/** Canonical names of every icon, sorted. */
export const iconNames: readonly string[] = [
${names}
];
`;
}

/** A string array on one line, or one entry per line when it would be too long. */
function renderStringArray(values, indentWidth) {
  if (values.length === 0) return "[]";
  const single = `[${values.map((value) => JSON.stringify(value)).join(", ")}]`;
  // The prefix is the longest key this helper is used for, plus its indent.
  if (indentWidth + "aliases: ".length + single.length + 1 <= LINE_WIDTH) return single;

  const indent = " ".repeat(indentWidth);
  const entries = values.map((value) => `${indent}  ${JSON.stringify(value)},`).join("\n");
  return `[\n${entries}\n${indent}]`;
}
